"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        base_name, arg_str = name.split(":", 1)
        if base_name not in STEPS:
            raise KeyError(f"no step named {base_name!r}. Known: {', '.join(sorted(STEPS))}")
        step_class = type(STEPS[base_name])
        if base_name == "truncate":
            if arg_str == "":
                raise ValueError(f"truncate step requires a length argument, got {name!r}")
            try:
                length = int(arg_str)
            except ValueError:
                raise ValueError(
                    f"truncate length must be an integer, got {arg_str!r}"
                )
            return Truncate(length)
        # For non-argument steps, ignore any accidental colon (shouldn't happen normally)
        return STEPS[base_name]
    else:
        if name not in STEPS:
            raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
        return STEPS[name]

